<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\SmtpOutboundConfigRef;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Service\Visibility\SmtpOutboundConfigVisibilityService;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\Gateway\SmtpOutboundConfigReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SmtpOutboundConfigRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SmtpOutboundConfigVisibilityService $visibility,
        private readonly SmtpOutboundConfigReadGateway $reader
    ) {
    }

    public function allowRetrieve(?SmtpOutboundConfigRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Smtp outbound config");
        $span = $this->startSpan("Check allow of retrieve usecase for Smtp outbound config");
        try {
            $result = $this->dispatcher->dispatch(new SmtpOutboundConfigRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?SmtpOutboundConfigRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Smtp outbound config");
        $span = $this->startSpan("Check hidden fields usecase for Smtp outbound config");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): SmtpOutboundConfigRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Smtp outbound config");
        $span = $this->startSpan("Run retrieve usecase for Smtp outbound config");
        try {
            $ref = new SmtpOutboundConfigRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Smtp outbound config');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new SmtpOutboundConfigRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
